#include <iostream>

template <typename T>
constexpr T add(T a, T b) {
  return a + b;
}

template <typename T>
constexpr T max(T a, T b) {
  return (a > b) ? a : b; 
}

template <typename T, typename U>
constexpr auto calculate(T a, U b) {
  if constexpr (std::is_integral_v<T> && std::is_integral_v<U>) {
    return add(a, b);
  } else if constexpr (std::is_floating_point_v<T> && std::is_floating_point_v<U>){
    return max(a,b);
  } else {
    return 0; //Handle other cases or throw an error
  }
}

int main() {
  constexpr int sum = calculate(5, 10);
  constexpr double max_val = calculate(3.14, 2.71);
  std::cout << "Sum: " << sum << std::endl; // Compile-time evaluated
  std::cout << "Max: " << max_val << std::endl; //Compile-time evaluated
  return 0;
}
